#!/usr/bin/env python3
"""Render docs/dsp_module_catalog.md from docs/dsp_module_catalog.json (made by tools/module_catalog_full.py).
usage: catalog_report.py docs/dsp_module_catalog.json docs/dsp_module_catalog.md"""
import json, sys
r = json.load(open(sys.argv[1])); out = []
P = out.append
PTS = 1100.0                      # instructions per 64-frame block per "DSP meter point" (calibration below)
def pts(n): return f'{n / PTS:.1f}'
def fx_desc(x):
    f, m, b = x['fx'], x['mod']['50'], x['behave']
    if m.get('silent'): return 'silent at all-50 / all-100, passes at all-0 (needs specific parameter values)'
    bands = '/'.join(f'{v:+.0f}' for v in f['bands_db'])
    tags = []
    if f['gain_quiet'] > 1.5 * f['gain_loud'] + 0.2: tags.append('level-dependent gain (compressor/limiter-like)')
    elif f['gain_loud'] > 1.25 * f['gain_quiet']: tags.append('gain rises with level')
    if m['am'] > 0.1: tags.append(f"AM {m['am']:.2f}")
    if m['sideband'] > 0.2: tags.append(f"sidebands {m['sideband']:.2f}")
    if abs(m['f_peak'] - 1000) > 30: tags.append(f"tone moves to {m['f_peak']:.0f} Hz")
    if f['f_out_440'] and abs(f['f_out_440'] - 441) > 40: tags.append(f"440 Hz in -> {f['f_out_440']:.0f} Hz out")
    if f['harm'] and f['harm'] > 0.05: tags.append(f"harmonics {f['harm']:.2f}")
    return f"bands 80/250/800/2.5k/6k/12k Hz {bands} dB; gain quiet/loud {f['gain_quiet']:.2f}/{f['gain_loud']:.2f}" + ('; ' + ', '.join(tags) if tags else '')
P('# DSP overlay modules of segment g (Cortex-M co-processor): catalog')
P('')
P('Generated by `tools/module_catalog_full.py` (probes) and `tools/catalog_report.py` (this file) from `docs/dsp_module_catalog.json`.')
P('All numbers come from running the **real firmware loader and module code in the unicorn Cortex-M4 emulator** (`tools/emu_host.py`), module by module, with all parameters set to 50 unless stated. **Confidence:** `V` = behaviour measured and consistent with an independent fact (CFW manual or data in the module); `I` = inferred (position/order or class only); `?` = unknown.')
P('')
P('## 1. What the groups are')
P('')
P('| group = slot | modules | UI block (evidence) | code base / size | engine data window (changed by the module) |')
P('|---|---|---|---|---|')
rows = [
 (0, 'Noise Gate', 'measured: -30 dB at an input of -30 dBFS, unity at -10 dBFS (V)', '0x10000000 / 0x1000', '-'),
 (1, 'FX1', '15 modules; the last is the only module that is not in FX2 (AC G, see below)', '0x10001000 / 0x1800', '-'),
 (2, 'DRV (drive/fuzz)', '8 modules, class from slot position (I)', '0x10002800 / 0x1000', '0x2800064c-0x280009de'),
 (3, 'AMP', '22 modules = the 22 stock amps (count + manual: Voks Bass is the last stock amp) (I)', '0x10003800 / 0x2c00', '0x28000e60-0x28001360'),
 (4, 'CAB / IR', '1 module (convolution setup, ~138k instructions in ENTRY1) (I)', '0x10006400 / 0x1800', '0x28001600-0x28003dfc (10 KB)'),
 (5, 'EQ', '3 modules = GT EQ 1, GT EQ 2, Bass EQ: their band-frequency tables match the manual exactly (V)', '0x10007c00 / 0x1400', '0x28003e70-0x28003f44'),
 (6, 'FX2', '17 modules = FX1 minus AC G, plus 3 extra (Pitch/Octave/Detune class) (V for the structure)', '0x10009000 / 0x3000', '-'),
 (7, 'DLY', '9 modules = the 9 stock delays; echoes measured (V)', '0x1000c000 / 0xc400', '-'),
 (8, 'RVB', '10 modules = the 10 stock reverbs; each only fills a parameter struct and calls the resident library (V)', '0x10018400 / 0x7000', '-'),
 (9, 'Clone (NAM) engine', '1 module of 9764 B, loads into the AMP slot (0x10003800, extended to 0x4400, data 0x28005400) (I)', '0x10003800 / 0x4400', '-'),
 (10, 'resident library', '1 blob (8312 B) copied raw to 0x10018800 with an export table; +1 stub', '0x10018800', '-')]
for g, blk, ev, base, win in rows:
    n = 1 if g in (0, 4, 9, 10) else sum(1 for k in r if k.startswith(f'{g}.'))
    P(f'| {g} | {n} | {blk}: {ev} | {base} | {win} |')
P('')
P('**What the modules are (important).** Only groups 0, 1, 6, 7 and 8 actually process audio inside the module (`ENTRY2`). In groups 2, 3, 4, 5 and 9 `ENTRY2` is a few dozen instructions: it latches the scaled parameters (`p * 0.01` etc.) and, for the amps, recomputes a block of filter coefficients into an engine data window, while the signal processing runs in the RAM-resident engine in segment c (`0x200009a1`). Their audio behaviour therefore **cannot be measured with the module-level harness** (the full-engine twin still routes silence into the chain, see FINDINGS section 21). For those groups this catalog gives sizes, parameter counts, coefficient-window usage and CPU cost of the module part only.')
P('')
P('**CPU cost.** `instr/blk` = emulated instructions of one `ENTRY2` call on a 64-frame stereo block (after warm-up, noise input). One block is 64/44100 s = 1.45 ms = 278,640 cycles at 192 MHz. The CFW manual quotes DSP-meter points for the stock choruses: A-Chorus about 13 points, B-Chorus about 6 points. Modules 1.5 and 1.6 measure 13,587 and 6,777 instructions: 1,045 and 1,130 instructions per point, so about **1,100 instructions per meter point** (used in the "pts" column; the ratio A:B = 2.0 against 2.2 in the manual is an independent confirmation that these two modules are the stock A-Chorus and B-Chorus).')
P('')
# ---- group 0
P('## 2. Group 0 — Noise Gate (slot 0)')
x = r['0.0']
P(f"| id | blob / payload / data | ENTRY1 / ENTRY2 | instr/blk (pts) | state | behaviour | name | conf |\n|---|---|---|---|---|---|---|---|")
P(f"| 0.0 | {x['blob']} / {x['payload']} / {x['data_block']} | {x['entry1']} / {x['entry2']} | {x['cost_block']} ({pts(x['cost_block'])}) | {x['state_bytes']} B | gain {x['behave']['gain_03']:.3f} at 0.03 amplitude, {x['behave']['gain_3']:.2f} at 0.3 and {x['behave']['gain_9']:.2f} at 0.9: a gate/expander (1 parameter read: threshold) | Noise Gate | V |")
P('')
def fxtable(group, names, ids):
    P('| id | blob / payload | ENTRY1 / ENTRY2 | instr/blk (pts) | state | params read E1 / E2 | measured behaviour (all params 50) | proposed name | conf |')
    P('|---|---|---|---|---|---|---|---|---|')
    for i in ids:
        x = r[f'{group}.{i}']; nm, cf = names.get(i, ('?', '?'))
        P(f"| {group}.{i} | {x['blob']} / {x['payload']} | {x['entry1']} / {x['entry2']} | {x['cost_block']} ({pts(x['cost_block'])}) | {x['state_bytes']} B | {x['params_entry1']} / {x['params_entry2']} | {fx_desc(x)} | {nm} | {cf} |")
fx1 = {0: ('COMP 1', 'I'), 1: ('COMP 2', 'I'), 2: ('Auto Wah', 'I'), 3: ('unidentified (strong AM/FM + low-pass + 15% harmonics)', '?'), 4: ('unidentified (silent unless the parameters are 0)', '?'),
       5: ('A-Chorus', 'V'), 6: ('B-Chorus', 'V'), 7: ('Flanger', 'I'), 8: ('Phaser', 'I'), 9: ('Vibe', 'I'), 10: ('Vibrato', 'I'), 11: ('Tremolo', 'I'), 12: ('Sine Trem', 'I'), 13: ('Bias Trem', 'I'), 14: ('AC G', 'I')}
P('## 3. Group 1 — FX1 (slot 1): 15 modules')
P('')
fxtable(1, fx1, range(15))
P('')
P('Notes: (a) the order 5 A-Chorus, 6 B-Chorus, 7 Flanger, 8 Phaser, 9 Vibe, 10 Vibrato, 11-13 Tremolo / Sine Trem / Bias Trem matches the order of modulation names in the CFW manual and the measured classes (chorus-like sidebands for 5-9, a moving pitch for 10, pure amplitude modulation for 11-13); 14 is the only FX1 module missing from FX2 and the manual says FX1 ends with AC G. (b) 1.6 (B-Chorus) has the strong high-frequency loss of the "dull dry guitar" the manual describes (-30 dB at 12-18 kHz). (c) 1.14 has a +23 dB high-frequency shelf and a -23 dB notch near 1 kHz at 0.06 overall gain, a typical acoustic-guitar-simulation curve. (d) 1.3 and 1.4 could not be named; 1.4 is silent with parameters 50 or 100 (it passes audio when they are 0, so its parameter meaning differs).')
P('')
fx2 = {0: ('COMP 1 (FX1 0)', 'I'), 1: ('COMP 2 (FX1 1)', 'I'), 2: ('Auto Wah (FX1 2)', 'I'), 3: ('= FX1 3', '?'), 4: ('Pitch', 'I'), 5: ('Octave', 'I'), 6: ('Detune', 'I'), 7: ('= FX1 4', '?')}
for k, i in enumerate(range(8, 17)): fx2[i] = (f'{fx1[k + 5][0]} (FX1 {k + 5})', fx1[k + 5][1])
P('## 4. Group 6 — FX2 (slot 6): 17 modules')
P('')
P('Modules 6.0-6.3 are the same code as 1.0-1.3 relinked to 0x10009000; 6.7-6.16 are 1.4-1.13 relinked; 6.4, 6.5 and 6.6 are the three extra modules (and 1.14 AC G does not exist in FX2). The relinked copies behave identically to their FX1 twins (same measured numbers); only the three extras are listed with their own behaviour below, the rest are in the JSON.')
P('')
fxtable(6, fx2, [4, 5, 6])
P('')
P('The extras keep a **5.2-5.4 KB state** (a pitch-shifter grain buffer) and cost 15.4k / 15.5k / 9.7k instructions per block, the heaviest FX modules. At the default parameters 6.5 turns a 1 kHz tone into about 3.97 kHz (two octaves up, a pitch-shifter fingerprint), 6.4 keeps the pitch (shift 0 at 50) with sidebands and 6.6 moves it by only a few Hz with small AM/FM (a detune). Names are inferred from the manual (FX2 has Pitch, Octave and Detune) and these measurements.')
P('')
# ---- group 2 / 3 / 4 / 5
def simple(group, names, ids, wincol=True):
    P('| id | blob / payload / data block | ENTRY1 / ENTRY2 | ENTRY1 instr | ENTRY2 instr | params read in ENTRY2 | engine data window changed | proposed name | conf |')
    P('|---|---|---|---|---|---|---|---|---|')
    for i in ids:
        x = r[f'{group}.{i}']; nm, cf = names.get(i, ('?', '?'))
        w = x.get('data_window'); w = f"{w[0]}-{w[1]} ({x.get('window_bytes_changed', 0)} B changed)" if w else '-'
        P(f"| {group}.{i} | {x['blob']} / {x['payload']} / {x['data_block']} | {x['entry1']} / {x['entry2']} | {x['cost_entry1']} | {x['cost_block']} | {x['params_entry2']} | {w} | {nm} | {cf} |")
P('## 5. Group 2 — DRV (slot 2): 8 modules')
P('')
P('Parameter-to-coefficient modules (`ENTRY2` only latches `p0*0.01`, `p2*0.01` etc. and sets a flag at the end of the window); the clipper/filter itself is engine code. No names recovered: the CFW manual mentions only "Grey Fuzz" as a stock drive. Module sizes 2748, 2048, 2644, 4308, 3384, 1208, 1188, 4532 bytes; the two smallest (2 parameters) are the simplest boost/fuzz-type circuits (I).')
P('')
simple(2, {}, range(8))
P('')
P('## 6. Group 3 — AMP (slot 3): 22 modules + group 9 (Clone engine)')
P('')
P('Each amp module reads 3 to 7 parameters (gain, tone controls, volume ...), scales them (`*0.01`, `*0.009` ...) into the engine window at `0x28001108`-ish and recomputes a six-coefficient filter block (a tone-stack style pole/zero design; checked in module 3.0, whose `p1` goes through polynomials with constants such as 0.494985 and 0.9899). **Names**: only two are inferable. A preset that names an unknown amp falls back to index 0, which the manual calls TWD Deluxe, and the last stock amp is Voks Bass (the manual: the Smart Box amps start after it). 3.21 is the smallest module (1556 B, 3 parameters), a fit for a bass amp. Modules 3.4, 3.17, 3.20 and 3.21 are linked differently from the rest (entry points 0x10003851 / 0x10003e35, no common slot-base pointer): probably amps with another tone-stack or a bass topology (?). 3.18 (12,128 B, ENTRY1 12,108 instructions) and 3.19 (9,908 B, 7,797 instructions) build large tables when selected (waveshaper or cabinet-like tables?).')
P('')
am = {0: ('TWD Deluxe', 'I'), 21: ('Voks Bass', 'I')}
simple(3, am, range(22))
P('')
x = r['9.0']
P('**Group 9 (Clone/NAM engine, slot 9 = AMP slot extended):** blob %d B (payload %d, data block %d), ENTRY1 %d instructions, ENTRY2 %d instructions (it passes audio through: `output_equals_input` = %s). Like the amps it only latches parameters; the neural-network inference is outside the module (I).' % (x['blob'], x['payload'], x['data_block'], x['cost_entry1'], x['cost_block'], x['output_equals_input']))
P('')
P('## 7. Group 4 — CAB / IR (slot 4)')
P('')
x = r['4.0']
P(f"One module, {x['blob']} B (payload {x['payload']}, data {x['data_block']}), ENTRY1 = **{x['cost_entry1']:,} instructions** (set-up on every cab change: FFT plan / partitioning), ENTRY2 = {x['cost_block']} instructions, parameter read in ENTRY2: {x['params_entry2']} (level). It touches a **10 KB data window `{x['data_window'][0]}-{x['data_window'][1]}`** (the convolution partitions/state live there). The 15 factory cabs and the user IRs are not in segment g (data comes from the storage regions, names from segment f). Name: CAB/IR convolution engine (I).")
P('')
P('## 8. Group 5 — EQ (slot 5): 3 modules, names verified')
P('')
P('The three modules are the same code and differ only in a table of five band centre frequencies at payload offset 0x384 (then 40.0 = a Q/width constant). **The tables are exactly the bands listed in the CFW manual**:')
P('')
P('| id | band frequencies (Hz) | name | conf |\n|---|---|---|---|')
for i, (bands, nm) in enumerate((('125 / 400 / 800 / 1600 / 4000', 'GT EQ 1'), ('100 / 500 / 1000 / 3000 / 6000', 'GT EQ 2'), ('50 / 120 / 400 / 800 / 4500', 'Bass EQ'))):
    P(f'| 5.{i} | {bands} | {nm} | V |')
P('')
simple(5, {0: ('GT EQ 1', 'V'), 1: ('GT EQ 2', 'V'), 2: ('Bass EQ', 'V')}, range(3))
P('')
# ---- group 7
P('## 9. Group 7 — DLY (slot 7): 9 modules')
P('')
P('Parameters (from ENTRY1): `p0` mix (`*0.01`), `p1` time (`*22.05` samples, clamped to a per-module range), `p2` feedback (`*0.005`). The modules run at a reduced rate (22.05 kHz or 11.025 kHz) so an impulse vanishes; they were measured with a 10 ms 1 kHz tone burst, mix 100, feedback 50. **Delay at time = 5 / 100 / 1000 ms** is the measured first-echo delay (relative to the 5 ms case = the 20 ms minimum); `wobble` = std of the output frequency of a continuous 1 kHz tone; `tilt` = output/input level in six bands (80 Hz ... 12-18 kHz).')
P('')
P('| id | blob | state (delay line) | instr/blk (pts) | delay @5 / 100 / 1000 ms | wobble Hz | tilt dB | proposed name | conf |')
P('|---|---|---|---|---|---|---|---|---|')
dn = {0: ('Pure', 'I'), 1: ('Slap', 'I'), 2: ('Warm', 'I'), 3: ('Mag', 'I'), 4: ('Tube', 'I'), 5: ('Reverse', 'I'), 6: ('Analog', 'I'), 7: ('Sweep', 'I'), 8: ('Ping Pong', 'I')}
for i in range(9):
    x = r[f'7.{i}']; db = x['delay_burst']; p5, p100, p1000 = db['5'][0][0], db['100'][0][0], db['1000'][0][0]
    d = lambda p: (p - p5) / 44.1 + 20
    tilt = '/'.join(f'{v:+.0f}' for v in x['delay_char']['bands_db'])
    P(f"| 7.{i} | {x['blob']} | {x['state_bytes']:,} B | {x['cost_block']} ({pts(x['cost_block'])}) | {20:.0f} / {d(p100):.0f} / {d(p1000):.0f} | {x['delay_char']['wobble_hz']} | {tilt} | {dn[i][0]} | {dn[i][1]} |")
P('')
P('Evidence for the names: the **index order equals the stock UI order** (Pure, Slap, Warm, Mag, Tube, Reverse, Analog, Sweep, Ping Pong), which agrees with every measurement: 7.1 has a half-size delay line (22 KB, 500 ms maximum; Slap), 7.5 and 7.8 have doubled time units (the time knob is up to 500 ms in the manual but the line is 1 s: the reverse-slice and ping-pong structures), 7.7 is the largest module with the strongest modulation (Sweep), 7.3 shows a slow wobble (tape: Mag), 7.6 a steep low-pass (BBD: Analog), 7.0 is flat and bright (Pure). Warm (7.2) and Tube (7.4) are the weakest assignments (their tilts are not obviously "warm" vs "tube").')
P('')
# ---- group 8
P('## 10. Group 8 — RVB (slot 8): 10 modules and the resident library (group 10)')
P('')
P('Each module (240-340 B) only fills a parameter struct at `0x100184e4` (mix, a decay/size scale, damping ...) and calls the **resident library** through the two function pointers at `0x10018800` / `0x10018804` (two references per module, verified by the code scan). The reverb algorithm is therefore in group 10 (8,312 B, export A at +0x5fc builds the working structures). Parameter indices differ per module (E2 reads p1 or p2 for the decay), so the table uses all non-mix parameters = 0 / 50 / 100 and an input burst (mix 100); `T30` = time for the envelope to fall 30 dB below its peak (the probe window ends at 2.8 s).')
P('')
P('| id | blob | params read in ENTRY2 | instr/blk (pts) | T30 s at params 0 / 50 / 100 | proposed name (UI order) | conf |')
P('|---|---|---|---|---|---|---|')
rv = ['Air', 'Room', 'Hall', 'Church', 'Plate 1', 'Plate 2', 'Spring', 'Light', 'Ocean', 'Dream']
for i in range(10):
    x = r[f'8.{i}']; t = x['reverb']; f = lambda k: t[k]['t30_s'] if t[k] else None
    P(f"| 8.{i} | {x['blob']} | {x['params_entry2']} | {x['cost_block']} ({pts(x['cost_block'])}) | {f('p0')} / {f('p50')} / {f('p100')} | {rv[i]} | I (low) |")
P('')
P('The UI-order hypothesis is confirmed for the delays but the reverb measurements do not settle it: Air (0.19 s) and Room (0.30 s) are short and Hall/Church longer, but 8.4 (Plate 1) and 8.7 (Light) have the longest tails at these settings, which contradicts "Light, short". The per-model decay ranges (the manual says up to about 13 s) are not reproduced by a 2.8 s window, so treat the names as order-based guesses. The library part costs about 24.4k instructions per block (about 22 points) for every reverb.')
P('')
P('## 11. Cross-checks that support the structure')
P('')
P('1. EQ band tables equal the manual: verified for all three EQ models.')
P('2. FX1 15 modules vs FX2 17: FX2 = FX1 without module 14 (AC G) plus three extras (Pitch, Octave, Detune): matches the CFW manual ("FX1 ends with AC G", "FX2: Pitch, Octave, Detune").')
P('3. Delay structure: nine modules, six with 1 s lines, one with 0.5 s, two with doubled time units, delay lines of 44,128 / 22,136 / ~44,150 bytes (int16 at 22.05 kHz): matches the manual\'s ranges (Slap 300 ms, Reverse and Ping Pong 500 ms, others 1000 ms).')
P('4. A-Chorus : B-Chorus cost = 2.0 (manual 13 : 6 points).')
P('5. Reverb modules are tiny and call the library (10 stock reverbs = 10 modules).')
P('')
P('## 12. Not done / limits')
P('')
P('- **No behavioural measurement for DRV, AMP, CAB and EQ** because their DSP is in the segment-c engine; the engine twin does not yet route audio through the chain (FINDINGS section 21).')
P('- Amp and drive **names** beyond the two amp indices (0 and 21) are unknown; the manual gives only a few names.')
P('- FX1 modules 1.3 and 1.4 are unidentified. All FX behaviour is for parameters 50 (and 0/100 for the modulation test); parameter meanings were not mapped one by one (the sweep in `docs/module_param_sweep.md` has the sensitivity per parameter).')
P('- The harness passes `args[0x14] = 0`; the real engine passes `60000 / halfword(state+8)` (set by a message from the other chip). Modules that depend on it may behave differently on the pedal.')
P('- Module state sizes were measured by pre-filling RAM (write hooks in this unicorn build corrupt multi-register stores, so they are not used).')
open(sys.argv[2], 'w').write('\n'.join(out) + '\n')
